resources.afterResponseScript:
// Extract the generated shortCode from the response body and store it
// in the environment so requests 2-4 in this folder can chain off it.
const body = insomnia.response.json();

if (!body || !body.shortCode) {
  throw new Error('Create response did not contain a shortCode - got: ' + insomnia.response.text());
}

insomnia.environment.set('shortCode', body.shortCode);
console.log('Stored shortCode for downstream requests:', body.shortCode);
